Author: maint-bot <maint-bot@example.invalid>
Date:   Fri Aug 28 22:24:44 2026 +0100

    Decode the QuickTime 'name' atom

    Store the object/track name carried by the 'name' atom as
    Xmp.video.Comment. decodeBlock already resizes the shared buffer to the
    atom size before dispatching, so the handler can read the payload back
    into it directly, matching how the other string atoms are handled.

    (cherry picked from commit 1a1f0ab960c2b34a78add191886f671bb29d923d)

diff --git a/src/quicktimevideo.cpp b/src/quicktimevideo.cpp
index 9a8b3c0..7f0e23f 100644
--- a/src/quicktimevideo.cpp
+++ b/src/quicktimevideo.cpp
@@ -707,6 +707,13 @@ void QuickTimeVideo::tagDecoder(Exiv2::DataBuf& buf, size_t size, size_t recursi
     xmpData_["Xmp.audio.Balance"] = buf.read_uint16(0, bigEndian);
   }

+  else if (equalsQTimeTag(buf, "name")) {
+    // The object/track name is stored as the atom payload. decodeBlock has
+    // already grown buf to hold the whole atom, so read it straight back.
+    io_->readOrThrow(buf.data(), size);
+    xmpData_["Xmp.video.Comment"] = std::string(buf.c_str(), size);
+  }
+
   else {
     discard(size);
   }

